import java.util.LinkedList;
import java.util.Scanner;

public class easy {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int how = in.nextInt();
        in.nextLine();
        String s = in.nextLine();
        boolean skb = false;
        String temp = "";
        int max = 0;
        LinkedList<String> arr = new LinkedList<String>();
        int i = 0;
        while (i < s.length()) {
            char c = s.charAt(i);
            i++;
            if (c == '(') {
                skb = true;
                if (temp.length() > max) max = temp.length();
                temp = "";
            }
            if (c == ')') {
                skb = false;
                if (temp.length() > 0) {
                    arr.add(temp);
                    temp = "";
                }
            }
            if (Character.isLetter(c)) {
                temp += c;
            }
            if (c == '_' && !skb) {
                if (temp.length() > max) max = temp.length();
                temp = "";
            }
            if (c == '_' && skb) {
                if (temp.length() > 0) {
                    arr.add(temp);
                    temp = "";
                }
            }
        }
        if (temp.length() > max) max = temp.length();
        System.out.println(max + " " + arr.size());
    }
}
